function getSID($koneksi) {
    $stmt = $koneksi->prepare("SELECT region FROM actived_server WHERE id = 4");
    if ($stmt) {
        $stmt->execute();
        $stmt->bind_result($sid);
        
        if ($stmt->fetch()) {
            return $sid;
        } else {
            return "❌ No server found with ID 2";
        }
        $stmt->close();
    } else {
        return "❌ Database error: Unable to prepare statement.";
    }
}

